"""Audit printed manuscript language; never read/generate scientific samples."""
import argparse
import re
from pathlib import Path
from paper_support import ROOT, json_write, sha256

PATTERNS = {
    "internal_id_hits": [r"\bT\d+[A-Z]?(?:-[A-Z]+)?\b", r"\bC\d+\b", r"\bB0\b", r"\bEndpoint\s+[ABC]\b", r"\b(?:PASS|FAIL)\b"],
    "meta_ai_hits": [r"\b(?:Codex|ChatGPT|LLM|prompt|agent)\b", r"\b(?:task sheet|AI assistant|coding assistant|AI-generated|using AI)\b", r"\b(?:we asked the AI|the model helped us|automatically generated by)\b"],
    "lab_notebook_style_hits": [r"\b(?:first we|then we|next we|after that|we found that|therefore we tried|in this experiment|the experiment was conducted|following the previous experiment|after several experiments|based on the previous task|according to our experimental workflow)\b", r"本实验验证|实验步骤如下|首先运行|接着测试|最终得到"],
    "overclaim_hits": [r"\b(?:novel|unprecedented|universal|state-of-the-art|optimal|guaranteed|fully robust|arbitrary shift|solves the problem|dramatically superior|fully blind|environment agnostic)\b", r"\b(?:remarkably|dramatically|extremely|obviously|impressive|powerful|effective solution)\b", r"\b(?:rank-?4 LMMSE estimator|independent physical factor|separable physical directions|profile component|mobility component)\b", r"\b(?:runtime speedup|low latency|real-time|hardware efficient|deployment acceleration)\b"],
    "forbidden_terminology_hits": [r"\b(?:preflight|gate|stop rule|formal (?:test|unseal|sealed|readiness)|claim ledger|research status(?: card)?|decision mapping)\b", r"\b(?:Git|SHA256|pytest|CSV row|resume script|seed collision repair|network interruption)\b", r"\b[\w-]+\.(?:py|npz|json|csv)\b", r"[A-Z]:[\\/]"],
}


def printed_tex(text):
    """Exclude comments and structural arguments, retaining printed math/prose."""
    text = re.sub(r"(?<!\\)%[^\n]*", "", text)
    if r"\begin{document}" in text:
        text = text.split(r"\begin{document}", 1)[1]
    text = re.sub(r"\\(?:input|include|label|ref|eqref|cite|citep|citet|bibliography|bibliographystyle)\*?(?:\[[^\]]*\])?\{[^}]*\}", "", text)
    return re.sub(r"\\includegraphics(?:\[[^\]]*\])?\{[^}]*\}", "", text)


def scan_text(text, name="snippet"):
    printed = printed_tex(text)
    hits = {}
    for category, patterns in PATTERNS.items():
        hits[category] = [dict(file=name, line=printed.count("\n", 0, m.start()) + 1,
                               text=m.group(), pattern=pattern)
                          for pattern in patterns for m in re.finditer(pattern, printed, re.I)]
    return hits


def audit(root=ROOT, output=None):
    root = Path(root)
    paths = sorted((root / "paper/sections").glob("*.tex")) + [root / "paper/main.tex"] + sorted((root / "paper/tables").glob("*.tex"))
    report = {category: [] for category in PATTERNS}
    for path in paths:
        result = scan_text(path.read_text(encoding="utf8"), path.relative_to(root).as_posix())
        for category in PATTERNS:
            report[category].extend(result[category])
    method = printed_tex((root / "paper/sections/04_proposed_method.tex").read_text(encoding="utf8"))
    report["notation_conflicts"] = [dict(pattern=pattern, reason=reason)
        for pattern,reason in ((r"r_{\ell f}","Residual reuses receive index r"),
                               (r"10^{-s/10}","SNR reuses source mnemonic s")) if pattern in method]
    report["manual_review_items"] = [dict(item, reason="technical meaning must be reviewed")
        for item in report["forbidden_terminology_hits"] if item["text"].lower() == "gate"]
    report["manual_semantic_review_required"] = True
    report["source_sha256"] = {p.relative_to(root).as_posix(): sha256(p) for p in paths}
    report["printed_internal_governance_leak_count"] = len(report["internal_id_hits"]) + len(report["forbidden_terminology_hits"])
    report["all_lexical_checks_passed"] = not any(report[k] for k in PATTERNS) and not report["notation_conflicts"]
    if output is not None:
        json_write(output, report)
    return report


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    result = audit(args.root, output=args.output)
    print({k: len(result[k]) for k in PATTERNS})
    if not result["all_lexical_checks_passed"]:
        raise SystemExit(1)
